window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-46df595ce84b19ab"]={"versions": [{"id": "FIG-46df595ce84b19ab", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des VFB-Timing-Metamodells im Kontext der AUTOSAR-Timing-Extensions. Es definiert die statische Struktur zur Verknüpfung von Timing-Beschreibungen und -Constraints mit Software-Komponententypen auf VFB-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ARPackage::ARElement</code>: Abstraktes Basiselement (<code>PackageableElement</code>).\n</li><li><code>Timing::TimingExtension</code>: Spezialisierung von <code>ARElement</code>, aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>, Multiplizität jeweils <code>0..*</code>):\n<ul class=\"fig-list\"><li><code>+timingDescription</code>: <code>Identifiable TimingDescription</code>\n</li><li><code>+timingRequirement</code>: <code>Identifiable Traceable TimingConstraint::TimingConstraint</code>\n</li><li><code>+timingGuarantee</code>: <code>Identifiable Traceable TimingConstraint::TimingConstraint</code>\n</li></ul>\n</li><li><code>Timing::VfbTiming</code>: Spezialisierung von <code>TimingExtension</code>, versehen mit Stereotypen <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Referenziert unidirektional:\n<ul class=\"fig-list\"><li><code>+component</code>: genau eine Zielkomponente (<code>1</code>) vom Typ <code>Components::SwComponentType</code> (versehen mit <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltenszustände. Es beschreibt Deklarationsstrukturen für Timing-Garantien, -Anforderungen und -Beschreibungen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>VfbTiming</code>-Element ist ein eigenständiges Top-Level-Paketelement (<code>ARElement</code>) und Blaupause (<code>AtpBlueprint</code>). Eine Instanz von <code>VfbTiming</code> erfordert zwingend die Assoziation zu genau einem <code>SwComponentType</code> (<code>Multiplizität 1</code>). Die Aggregationen für Beschreibungen und Constraints unterstützen AUTOSAR-Variabilität und Modell-Splitting (<code>«atpVariation,atpSplitable»</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-25a1ed37e0d0c7e8", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des VFB-Timing-Metamodells im Kontext der AUTOSAR-Timing-Extensions. Es definiert die statische Struktur zur Verknüpfung von Timing-Beschreibungen und -Constraints mit Software-Komponententypen auf VFB-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ARElement</code>: Abstraktes Basiselement (<code>PackageableElement</code>).\n</li><li><code>TimingExtension</code>: Spezialisierung von <code>ARElement</code>, aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>, Multiplizität jeweils <code>0..*</code>):\n<ul class=\"fig-list\"><li><code>+timingDescription</code>: <code>Identifiable TimingDescription</code>\n</li><li><code>+timingRequirement</code>: <code>Identifiable Traceable TimingConstraint</code>\n</li><li><code>+timingGuarantee</code>: <code>Identifiable Traceable TimingConstraint</code>\n</li></ul>\n</li><li><code>VfbTiming</code>: Spezialisierung von <code>TimingExtension</code>, versehen mit Stereotypen <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Referenziert unidirektional:\n<ul class=\"fig-list\"><li><code>+component</code>: genau eine Zielkomponente (<code>1</code>) vom Typ <code>SwComponentType</code> (versehen mit <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltenszustände. Es beschreibt Deklarationsstrukturen für Timing-Garantien, -Anforderungen und -Beschreibungen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>VfbTiming</code>-Element ist ein eigenständiges Top-Level-Paketelement (<code>ARElement</code>) und Blaupause (<code>AtpBlueprint</code>). Eine Instanz von <code>VfbTiming</code> erfordert zwingend die Assoziation zu genau einem <code>SwComponentType</code> (<code>Multiplizität 1</code>). Die Aggregationen für Beschreibungen und Constraints unterstützen AUTOSAR-Variabilität und Modell-Splitting (<code>«atpVariation,atpSplitable»</code>).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a644adeffe347f06", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des VFB-Timing-Metamodells im Kontext der AUTOSAR-Timing-Extensions. Es definiert die statische Struktur zur Verknüpfung von Timing-Beschreibungen und -Constraints mit Software-Komponententypen auf VFB-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>ARElement</code>: Abstraktes Basiselement (<code>PackageableElement</code>).\n</li><li><code>TimingExtension</code>: Spezialisierung von <code>ARElement</code>, aggregiert per Komposition (<code>«atpVariation,atpSplitable»</code>, Multiplizität jeweils <code>0..*</code>):\n<ul class=\"fig-list\"><li><code>+timingDescription</code>: <code>Identifiable TimingDescription</code>\n</li><li><code>+timingRequirement</code>: <code>Identifiable Traceable TimingConstraint</code>\n</li><li><code>+timingGuarantee</code>: <code>Identifiable Traceable TimingConstraint</code>\n</li></ul>\n</li><li><code>VfbTiming</code>: Spezialisierung von <code>TimingExtension</code>, versehen mit Stereotypen <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Referenziert unidirektional:\n<ul class=\"fig-list\"><li><code>+component</code>: optionale Zielkomponente (<code>0..1</code>) vom Typ <code>SwComponentType</code> (versehen mit <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe oder Verhaltenszustände. Es beschreibt Deklarationsstrukturen für Timing-Garantien, -Anforderungen und -Beschreibungen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>VfbTiming</code>-Element ist ein eigenständiges Top-Level-Paketelement (<code>ARElement</code>) und Blaupause (<code>AtpBlueprint</code>). Die Assoziation <code>+component</code> zu einem <code>SwComponentType</code> ist optional (<code>Multiplizität 0..1</code>). Die Aggregationen für Beschreibungen und Constraints unterstützen AUTOSAR-Variabilität und Modell-Splitting (<code>«atpVariation,atpSplitable»</code>).</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-46df595ce84b19ab", "to": "FIG-25a1ed37e0d0c7e8", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Paket-Präfixe in Klassennamen entfernt:\n<ul class=\"fig-list\"><li><code>ARPackage::ARElement</code> zu <code>ARElement</code>\n</li><li><code>Timing::TimingExtension</code> zu <code>TimingExtension</code>\n</li><li><code>Timing::VfbTiming</code> zu <code>VfbTiming</code>\n</li><li><code>Components::SwComponentType</code> zu <code>SwComponentType</code>\n</li><li><code>TimingConstraint::TimingConstraint</code> zu <code>TimingConstraint</code>\n</li></ul>\n</li></ul>"}, {"from": "FIG-25a1ed37e0d0c7e8", "to": "FIG-a644adeffe347f06", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Assoziation <code>VfbTiming</code> zu <code>SwComponentType</code> (<code>+component</code>): Multiplizität von <code>1</code> auf <code>0..1</code> gelockert.\n</li></ul>"}]};
